<?php declare(strict_types=1);namespace StudPulse\Security;final class LoginPassword{public static function key(string$login):string{return Crypto::hash('bars-login:'.strtolower(trim($login)));}public static function hash(#[\SensitiveParameter]string$password):string{return password_hash(Crypto::hash('bars-password:'.$password),PASSWORD_BCRYPT,['cost'=>12]);}public static function verify(#[\SensitiveParameter]string$password,string$hash):bool{return password_verify(Crypto::hash('bars-password:'.$password),$hash);}}